/// Game-wide constants for Harita: Kendi İmparatorluğunu Kur.
///
/// All magic numbers used across the codebase should be referenced
/// from this file to ensure consistency and ease of configuration.
library;

// ─── Map ────────────────────────────────────────────────────────────────────

/// Total number of territories ("minik kare" tiles) on the Africa map.
///
/// Must match `assets/maps/territory_graph.json`, which is generated by
/// `tool/generate_africa_map.py`.
const int kTerritoryCount = 227;

/// Units placed on each starting tile of both armies.
const int kStartUnitsPerTile = 5;

/// Number of tiles each army owns at game start (grown from its start base).
const int kStartTileCount = 10;

// ─── Base capacities ────────────────────────────────────────────────────────

/// Maximum unit capacity for a Big Base territory.
const int kBigBaseCapacity = 150;

// ─── Ability unlock turns ───────────────────────────────────────────────────

/// Turn at which the Bombardment ability becomes available.
const int kTurnUnlockBombardment = 10;

/// Turn at which the Soldier Spell ability becomes available.
const int kTurnUnlockSoldierSpell = 12;

/// Turn at which the Mega Bomba ability becomes available.
const int kTurnUnlockMegaBomba = 45;

/// The Direct Laser cooldown duration (in turns) after each use.
const int kDirectLaserCooldown = 3;

// ─── Economy ─────────────────────────────────────────────────────────────────

/// Elma (apple currency) earned per base owned at the start of each turn.
const int kElmaPerBase = 10;

/// Soldier units added to the unit pool at the start of each turn.
const int kSoldiersPerTurn = 3;

/// One extra soldier per turn for every this-many tiles owned.
const int kTilesPerBonusSoldier = 5;

/// Extra soldiers per turn granted to the bot on "Zor" (hard) difficulty.
const int kHardAiBonusSoldiers = 3;

// ─── Ability tile captures ("minik kare") ───────────────────────────────────

/// Tiles captured by the Fire Bomb.
const int kFireBombTiles = 1;

/// Tiles captured by the Bombardment.
const int kBombardmentTiles = 3;

/// Tiles captured by the Direct Laser (the instant 🔫 card).
const int kDirectLaserTiles = 5;

/// Tiles captured by the Mega Bomba.
const int kMegaBombaTiles = 9;

/// Units left on every tile captured by an ability.
const int kCapturedTileUnits = 1;

/// Units added to a friendly tile by the Soldier Spell.
const int kSoldierSpellUnits = 15;

// ─── Layout breakpoints ──────────────────────────────────────────────────────

/// Screen width (in dp) at or above which the tablet layout is used.
const double kPhoneBreakpoint = 600;

// ─── AI ──────────────────────────────────────────────────────────────────────

/// Minimum artificial delay (ms) between AI actions for visual legibility.
const int kAiActionDelayMinMs = 300;

/// Maximum artificial delay (ms) between AI actions for visual legibility.
const int kAiActionDelayMaxMs = 500;

/// Delay (ms) between AI actions once the bot has made many moves in a turn,
/// so that long turns on the big tile map stay quick.
const int kAiFastActionDelayMs = 60;

/// After this many actions in one turn the bot switches to the fast delay.
const int kAiSlowActionCount = 6;

/// Minimum unit ratio (AI : enemy) required for AI to attack an enemy territory.
const double kAiAttackOddsThreshold = 1.5;

// ─── Combat ──────────────────────────────────────────────────────────────────

/// Fraction of defending units the attacker loses when winning a combat.
const double kAttackerWinLossFraction = 0.5;

/// Fraction of attacking units the defender loses when holding a territory.
const double kDefenderHoldLossFraction = 0.3;
